     */
    API_MESSAGES_LOADED: 'aiuxc:API_MESSAGES_LOADED';
    /**
     * @description Fired when a new message is recorded via API or DOM fallback.
     */
    API_MESSAGE_ADDED: 'aiuxc:API_MESSAGE_ADDED';

