// @updateURL    https://update.greasyfork.org/scripts/604910.meta.js
// @downloadURL  https://update.greasyfork.org/scripts/604910.user.js
// @match        https://github.com/*
// @run-at       document-start
// @noframes
// @grant        none
// ==/UserScript==
